<include file="Publics:header"/>	<div class="mainbox">		<if condition="$_GET['source'] neq 'sys'">			<div class="form-group">				<label class="col-sm-1" style="width: 15%;"><label for="diy_village_name">是否显示装修内容</label></label>				<div class="radio" style="padding-top: 5px;">					<label style="padding-left:0px;padding-right:20px;"><input name="is_guess_like" value="1" type="radio" class="ace" <if condition="$village_nav.is_guess_like eq 1 ">checked</if>/><span class="lbl" style="z-index: 1">开启</span></label>					<label style="padding-left:0px;"><input name="is_guess_like" value="0" type="radio" class="ace" <if condition="$village_nav.is_guess_like eq 0 ">checked</if>/><span class="lbl" style="z-index: 1">关闭</span></label>				</div>			</div>			<div style="margin-left: 10px;color: #9a9999">				<span> 说明：</span>				<p>1.开关按钮默认开启</p>				<p> 2.按钮开关不控制系统的商品推荐，将控制自定义装修内容，关闭则装修的不展示</p>				<p> 3.总平台设置的活动不允许操作</p>			</div>		</if>		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('index_guess_like',$_GET)}" class="on">猜你喜欢</a>|				<if condition="$assign_type['type_10'] || $_GET['source'] eq sys">				<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('index_guess_add',array('source' => $_GET['source']))}','添加',850,580,true,false,false,addbtn,'add',true);">添加</a>				</if>			</ul>		</div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>排序</th>							<th>活动标题</th>							<th>状态</th>							<if condition="$assign_type['type_10'] || $_GET['source'] eq sys">							<th>关联店铺</th>							<th class="textcenter">操作</th>							</if>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.sort}</td>									<td>{pigcms{$vo.title}</td>									<td>										<if condition="$vo['status'] eq 1">											启用										<elseif condition="$vo['status'] eq 0"/>											关闭										</if>									</td>									<if condition="$assign_type['type_10'] || $_GET['source'] eq sys">									<td>										<if condition="$vo.village_id gt 0 || $_GET['source'] eq sys">											<a href="javascript:void(0);" class="related_store" onclick="window.top.artiframe('{pigcms{:U('index_guess_store',array('id'=>$vo['id']))}','关联店铺',660,540,true,false,false,false,'viewpage',true);">关联店铺</a>										</if>									</td>									<td class="textcenter">										<if condition="$vo.village_id gt 0 || $_GET['source'] eq sys">										<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('index_guess_edit',array('id'=>$vo['id']))}','编辑信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('index_guess_del')}">删除</a>										</if>									</td>									</if>								</tr>							</volist>						<else/>							<tr>								<td class="textcenter red" colspan="5">列表为空！</td>							</tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>	</div><style>    .related_store {        margin: 10px 0;        padding: 10px 20px;        border: 1px dashed #CCCCCC;        background-color: #ffffff;        display: inline-block;    }    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }</style><script>    $("input[name=is_guess_like]").change(function(){        var is_guess_like = $(this).val();      layer.confirm("是否保存显示装修内容设置?",{        btn: ['确认', '取消']      }, function () {        var url ="{pigcms{:U('Library/set_village_nav')}";        $.post(url,{'is_guess_like': is_guess_like},function(data){          layer.msg(data['msg'])        },'json')      }, function(){        if(is_guess_like == 1){          $("input[name=is_guess_like][type=radio][value='0']").attr("checked",true);        }else{          $("input[name=is_guess_like][type=radio][value='1']").attr("checked",true);        }      });    });</script><include file="Publics:footer"/>